import itertools

def get_tilings(n):
    cells = [(r, c) for r in range(n) for c in range(n)]
    tilings = []

    def solve(remaining_cells, current_tiling):
        if not remaining_cells:
            tilings.append(list(current_tiling))
            return

        r, c = min(remaining_cells)

        # Try horizontal
        if c + 1 < n and (r, c + 1) in remaining_cells:
            current_tiling.append(((r, c), (r, c + 1)))
            solve(remaining_cells - {(r, c), (r, c + 1)}, current_tiling)
            current_tiling.pop()

        # Try vertical
        if r + 1 < n and (r + 1, c) in remaining_cells:
            current_tiling.append(((r, c), (r + 1, c)))
            solve(remaining_cells - {(r, c), (r + 1, c)}, current_tiling)
            current_tiling.pop()

    solve(set(cells), [])
    return tilings

def is_compatible(tiling, marked_cells):
    for domino in tiling:
        if domino[0] in marked_cells and domino[1] in marked_cells:
            return False
    return True

def find_min_k(n):
    cells = list(itertools.product(range(n), range(n)))
    tilings = get_tilings(n)

    for k in range(1, n*n + 1):
        for marked_cells in itertools.combinations(cells, k):
            marked_set = set(marked_cells)
            compatible_tilings = [t for t in tilings if is_compatible(t, marked_set)]
            if len(compatible_tilings) == 1:
                return k
    return None

print(f"n=2: {find_min_k(2)}")
print(f"n=4: {find_min_k(4)}")

